-- Access administration is a central trust boundary; legacy grants never delegate it.
-- Full-schema regression exposed an existing collision with user_subsidiaries.id.
do $$declare d text;begin if to_regprocedure('company_master_private.save(text,jsonb,bigint)')is not null then
 select pg_get_functiondef('company_master_private.save(text,jsonb,bigint)'::regprocedure)into d;
 d:=replace(replace(d,'us.subsidiary_id=id','us.subsidiary_id=save.id'),'e.subsidiary_id=id','e.subsidiary_id=save.id');execute d;
 select pg_get_functiondef('company_master_private.member(bigint)'::regprocedure)into d;execute replace(d,'us.subsidiary_id=id','us.subsidiary_id=$1');end if;end$$;
create schema access_admin_private;
revoke all on schema access_admin_private from public,anon,authenticated,service_role;
grant usage on schema access_admin_private to authenticated;

create function access_admin_private.actor()returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=public.app_user_id();r bigint:=public.app_active_role_id();s bigint:=public.active_subsidiary_id();
begin if u is null or r is null or s is null or not exists(select 1 from public.users where user_id=u and is_active)or not exists(select 1 from public.user_roles where user_id=u and role_id=r)or not exists(select 1 from public.user_subsidiaries where user_id=u and subsidiary_id=s)then raise exception using errcode='42501',message='Contexto de seguridad no autorizado.';end if;return u;end$$;
create function access_admin_private.central()returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.roles where role_id=public.app_active_role_id()and is_system_role and lower(btrim(role_name))in('administrador','administrator','admin'))$$;
create function access_admin_private.access(k text,a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=access_admin_private.actor();b boolean;
begin if k not in('users','roles','user-roles','user-subsidiaries','permissions','role-permissions','role-access-matrix')or a not in('view','create','edit','delete')then raise exception using errcode='42501',message='Operacion no autorizada.';end if;
 if access_admin_private.central()then return u;end if;
 if a<>'view'and not(k='users'and a='edit')or k in('role-access-matrix','role-permissions','user-subsidiaries')then raise exception using errcode='42501',message='La administracion de accesos requiere un administrador central.';end if;
 select exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='security:'||k and m.can_view and case a when'view'then true when'edit'then m.can_edit else false end)into b;
 if not b then raise exception using errcode='42501',message='Requiere permiso explicito de seguridad.';end if;return u;end$$;
create function access_admin_private.allowed(k text,a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access(k,a);return true;exception when insufficient_privilege then return false;end$$;
create function access_admin_private.target(target_id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select access_admin_private.central()or exists(select 1 from public.user_subsidiaries where user_id=target_id and subsidiary_id=public.active_subsidiary_id())$$;
create function access_admin_private.admin_user(target_id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.user_roles ur join public.roles r using(role_id)where ur.user_id=target_id and r.is_system_role and lower(btrim(r.role_name))in('administrador','administrator','admin'))$$;
create function access_admin_private.revision(k text,target_id bigint)returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
select md5(case k when'users'then(select to_jsonb(u)::text from public.users u where user_id=target_id)
when'roles'then(select to_jsonb(r)::text from public.roles r where role_id=target_id)
when'user-roles'then(select to_jsonb(r)::text from public.user_roles r where r.id=target_id)
when'user-subsidiaries'then jsonb_build_array((select is_active from public.users where user_id=target_id),(select jsonb_agg(to_jsonb(r)order by subsidiary_id)from public.user_subsidiaries r where user_id=target_id))::text end)$$;
create function access_admin_private.matrix_revision(target_id bigint)returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select md5(jsonb_build_array((select to_jsonb(r)from public.roles r where role_id=target_id),(select jsonb_agg(to_jsonb(m)order by resource_key)from public.role_access_matrix m where role_id=target_id),(select jsonb_agg(to_jsonb(p)order by permission_id)from public.role_permissions p where role_id=target_id))::text)$$;

-- Preserve proven invitation, audit and bulk-assignment behavior behind checked wrappers.
alter function public.security_create_user(text,uuid,text,text,bigint,boolean)set schema access_admin_private;
alter function public.security_mark_user_invitation_sent(bigint)set schema access_admin_private;
alter function public.security_prepare_user_password_recovery(bigint)set schema access_admin_private;
alter function public.security_sync_user_subsidiaries(bigint,bigint[])set schema access_admin_private;
alter function public.security_user_subsidiary_assignments()set schema access_admin_private;
alter function public.security_user_subsidiary_options()set schema access_admin_private;
alter function public.security_role_access_matrix_data(bigint)set schema access_admin_private;
alter function public.security_save_role_access_matrix(bigint,jsonb,bigint[])set schema access_admin_private;

create function public.security_create_user(p_email text,p_auth_user_id uuid,p_first_name text,p_last_name text,p_timezone_id bigint default null,p_is_active boolean default true)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access('users','create');if p_timezone_id is not null and not exists(select 1 from public.timezones where timezone_id=p_timezone_id and is_active)then raise exception using errcode='22023',message='Zona horaria no disponible.';end if;return access_admin_private.security_create_user(p_email,p_auth_user_id,p_first_name,p_last_name,p_timezone_id,p_is_active);end$$;
create function public.security_mark_user_invitation_sent(p_user_id bigint)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access('users','create');return access_admin_private.security_mark_user_invitation_sent(p_user_id);end$$;
create function public.security_prepare_user_password_recovery(p_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access('users','edit');if not access_admin_private.target(p_user_id)or(not access_admin_private.central()and access_admin_private.admin_user(p_user_id))then raise exception using errcode='42501',message='Usuario no autorizado.';end if;return access_admin_private.security_prepare_user_password_recovery(p_user_id);end$$;
create function public.security_sync_user_subsidiaries(p_user_id bigint,p_subsidiary_ids bigint[])returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin raise exception using errcode='42501',message='Use el guardado de accesos con revision vigente.';end$$;
create function public.security_user_subsidiary_assignments()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access('user-subsidiaries','view');return(select coalesce(jsonb_agg(x||jsonb_build_object('_revision',access_admin_private.revision('user-subsidiaries',(x->>'user_id')::bigint),'_actions',jsonb_build_object('canEdit',(x->>'user_id')::bigint<>public.app_user_id(),'canDelete',false))),'[]')from jsonb_array_elements(access_admin_private.security_user_subsidiary_assignments())x);end$$;
create function public.security_user_subsidiary_options()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform access_admin_private.access('user-subsidiaries','view');return access_admin_private.security_user_subsidiary_options();end$$;
create function public.security_role_access_matrix_data(p_role_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d jsonb;begin perform access_admin_private.access('role-access-matrix','view');d:=access_admin_private.security_role_access_matrix_data(p_role_id);return d||jsonb_build_object('_revision',access_admin_private.matrix_revision((d->>'selectedRoleId')::bigint));end$$;
create function public.security_save_role_access_matrix(p_role_id bigint,p_entries jsonb,p_permission_ids bigint[] default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin raise exception using errcode='42501',message='Use la matriz con revision vigente.';end$$;
create function public.security_save_access_matrix(p_role_id bigint,p_entries jsonb,p_permission_ids bigint[],p_revision text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare result jsonb;
begin perform access_admin_private.access('role-access-matrix','edit');perform pg_advisory_xact_lock(793152,1);
 if not exists(select 1 from public.roles where role_id=p_role_id)or p_revision is distinct from access_admin_private.matrix_revision(p_role_id)then raise exception using errcode='55000',message='La matriz cambio. Consulte nuevamente.';end if;
 if jsonb_typeof(p_entries)is distinct from'array'or jsonb_array_length(p_entries)>1500 or pg_column_size(p_entries)>1000000 or exists(select 1 from jsonb_array_elements(p_entries)e where jsonb_typeof(e)<>'object'or exists(select 1 from jsonb_object_keys(e)k where k not in('resourceKey','canView','canCreate','canEdit','canDelete'))or coalesce(e->>'resourceKey','')='legacy:all'or exists(select 1 from jsonb_each(e)f where f.key<>'resourceKey'and jsonb_typeof(f.value)<>'boolean')or((coalesce((e->>'canCreate')::boolean,false)or coalesce((e->>'canEdit')::boolean,false)or coalesce((e->>'canDelete')::boolean,false))and not coalesce((e->>'canView')::boolean,false)))or exists(select 1 from jsonb_array_elements(p_entries)e group by e->>'resourceKey' having count(*)>1)then raise exception using errcode='22023',message='Matriz invalida.';end if;
 if p_permission_ids is null or exists(select 1 from unnest(p_permission_ids)x where x is null or not exists(select 1 from public.permissions p where p.permission_id=x and p.is_operational))or cardinality(p_permission_ids)<>(select count(distinct x)from unnest(p_permission_ids)x)then raise exception using errcode='22023',message='Permisos invalidos.';end if;
 result:=access_admin_private.security_save_role_access_matrix(p_role_id,p_entries,p_permission_ids);return result||jsonb_build_object('_revision',access_admin_private.matrix_revision(p_role_id));end$$;

create function public.security_access_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=access_admin_private.access(p_catalog,'view');d jsonb;
begin if p_catalog='user-subsidiaries'then return public.security_user_subsidiary_assignments();end if;
 if p_catalog='users'then select coalesce(jsonb_agg(jsonb_build_object('user_id',r.user_id,'email',r.email,'first_name',r.first_name,'last_name',r.last_name,'timezone_id',r.timezone_id,'is_active',r.is_active,'_revision',access_admin_private.revision(p_catalog,r.user_id),'_actions',jsonb_build_object('canEdit',access_admin_private.allowed('users','edit')and(r.user_id<>u or r.is_active)and(access_admin_private.central()or not access_admin_private.admin_user(r.user_id)),'canDelete',false))order by r.user_id),'[]')into d from public.users r where access_admin_private.target(r.user_id);
 elsif p_catalog='roles'then select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('_revision',access_admin_private.revision(p_catalog,r.role_id),'_actions',jsonb_build_object('canEdit',access_admin_private.central()and not r.is_system_role,'canDelete',false))order by r.role_id),'[]')into d from public.roles r;
 elsif p_catalog='user-roles'then select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('_revision',access_admin_private.revision(p_catalog,r.id),'_actions',jsonb_build_object('canEdit',access_admin_private.central()and r.user_id<>u,'canDelete',access_admin_private.central()and r.user_id<>u))order by r.id),'[]')into d from public.user_roles r where access_admin_private.target(r.user_id);
 elsif p_catalog='permissions'then select coalesce(jsonb_agg(to_jsonb(r)order by permission_id),'[]')into d from public.permissions r;
 elsif p_catalog='role-permissions'then select coalesce(jsonb_agg(to_jsonb(r)order by id),'[]')into d from public.role_permissions r;
 else raise exception using errcode='42501',message='Catalogo no disponible.';end if;return d;end$$;
create function public.security_access_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
begin perform access_admin_private.access(p_catalog,'view');return jsonb_build_object('canView',true,'canCreate',p_catalog in('users','roles','user-roles')and access_admin_private.central(),'canEdit',p_catalog in('users','roles','user-roles','user-subsidiaries')and access_admin_private.allowed(p_catalog,'edit'),'canDelete',p_catalog='user-roles'and access_admin_private.central(),'references',jsonb_build_object('security/users',case when p_catalog in('user-roles','user-subsidiaries')then(select coalesce(jsonb_agg(jsonb_build_object('user_id',user_id,'email',email,'first_name',first_name,'last_name',last_name)),'[]')from public.users where access_admin_private.target(user_id))else'[]'::jsonb end,'security/roles',case when p_catalog='user-roles'then(select coalesce(jsonb_agg(jsonb_build_object('role_id',role_id,'role_name',role_name)),'[]')from public.roles)else'[]'::jsonb end,'core/timezones',(select coalesce(jsonb_agg(jsonb_build_object('timezone_id',timezone_id,'name',name)),'[]')from public.timezones where is_active),'organization/subsidiaries',case when p_catalog='user-subsidiaries'then public.security_user_subsidiary_options()else'[]'::jsonb end));end$$;

create function public.security_save_access_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=access_admin_private.access(p_catalog,case when p_id is null then'create'else'edit'end);olduser public.users;oldrole public.roles;oldlink public.user_roles;id bigint:=p_id;fields text[];d jsonb;
begin perform pg_advisory_xact_lock(793152,1);fields:=case p_catalog when'users'then array['email','first_name','last_name','timezone_id','is_active']when'roles'then array['role_name','description','is_system_role']when'user-roles'then array['user_id','role_id']when'user-subsidiaries'then array['user_id','subsidiary_ids']end;
 if fields is null or jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>50000 or exists(select 1 from jsonb_object_keys(p_payload)x where not x=any(fields||array['_revision']))or(p_id is not null and(p_id<=0 or p_payload->>'_revision'is null or access_admin_private.revision(p_catalog,p_id)is null or p_payload->>'_revision'is distinct from access_admin_private.revision(p_catalog,p_id)))then raise exception using errcode='55000',message='Registro invalido o modificado. Consulte nuevamente.';end if;
 if p_catalog='users'then
  if p_id is null then raise exception using errcode='42501',message='Utilice la invitacion segura.';end if;select *into olduser from public.users where user_id=id for update;
  if not found or not access_admin_private.target(id)or(not access_admin_private.central()and access_admin_private.admin_user(id))then raise exception using errcode='42501',message='Usuario no autorizado.';end if;
  if p_payload?'email'and lower(btrim(p_payload->>'email'))is distinct from lower(btrim(olduser.email))then raise exception using errcode='42501',message='La identidad de acceso es inmutable.';end if;
  if (p_payload?'is_active'and jsonb_typeof(p_payload->'is_active')<>'boolean')or exists(select 1 from unnest(array['first_name','last_name'])f where p_payload?f and(jsonb_typeof(p_payload->f)<>'string'or length(btrim(p_payload->>f))not between 1 and 120))then raise exception using errcode='22023',message='Perfil invalido.';end if;
  if p_payload?'is_active'and not(p_payload->>'is_active')::boolean and olduser.is_active then if id=u or(access_admin_private.admin_user(id)and not exists(select 1 from public.users a where a.is_active and a.user_id<>id and access_admin_private.admin_user(a.user_id)))then raise exception using errcode='42501',message='No puede desactivar su cuenta ni al ultimo administrador.';end if;end if;
  if nullif(p_payload->>'timezone_id','')is not null and not exists(select 1 from public.timezones where timezone_id=(p_payload->>'timezone_id')::bigint and is_active)then raise exception using errcode='22023',message='Zona horaria no disponible.';end if;
  update public.users set first_name=case when p_payload?'first_name'then btrim(p_payload->>'first_name')else first_name end,last_name=case when p_payload?'last_name'then btrim(p_payload->>'last_name')else last_name end,timezone_id=case when p_payload?'timezone_id'then nullif(p_payload->>'timezone_id','')::bigint else timezone_id end,is_active=case when p_payload?'is_active'then(p_payload->>'is_active')::boolean else is_active end where user_id=id;
  if p_payload->>'is_active'='false'then delete from public.user_role_sessions where user_id=id;delete from public.user_company_sessions where user_id=id;end if;
 elsif p_catalog='roles'then
  if id is not null then select *into oldrole from public.roles where role_id=id for update;if oldrole.is_system_role then raise exception using errcode='42501',message='Los roles de sistema son inmutables.';end if;end if;
  if coalesce((p_payload->>'is_system_role')::boolean,false)or lower(btrim(coalesce(p_payload->>'role_name',oldrole.role_name,'')))in('administrador','administrator','admin')or length(btrim(coalesce(p_payload->>'role_name',oldrole.role_name,'')))not between 1 and 120 or length(coalesce(p_payload->>'description',''))>2000 then raise exception using errcode='22023',message='Rol invalido o reservado.';end if;
  if id is null then insert into public.roles(role_name,description,is_system_role)values(btrim(p_payload->>'role_name'),p_payload->>'description',false)returning role_id into id;else update public.roles set role_name=coalesce(btrim(p_payload->>'role_name'),role_name),description=case when p_payload?'description'then p_payload->>'description'else description end where role_id=id;end if;
 elsif p_catalog='user-roles'then
  if id is not null then select *into oldlink from public.user_roles where user_roles.id=p_id for update;if oldlink.user_id=u then raise exception using errcode='42501',message='No puede modificar sus propios roles.';end if;end if;
  if (p_payload->>'user_id')::bigint=u or not exists(select 1 from public.users where user_id=(p_payload->>'user_id')::bigint and is_active)or not exists(select 1 from public.roles where role_id=(p_payload->>'role_id')::bigint)then raise exception using errcode='42501',message='Asignacion no autorizada.';end if;
  if id is not null and access_admin_private.admin_user(oldlink.user_id)and not exists(select 1 from public.users a where a.is_active and a.user_id<>oldlink.user_id and access_admin_private.admin_user(a.user_id))and exists(select 1 from public.roles where role_id=oldlink.role_id and lower(btrim(role_name))in('administrador','administrator','admin'))then raise exception using errcode='42501',message='Conserve al ultimo administrador.';end if;
  if id is null then insert into public.user_roles(user_id,role_id)values((p_payload->>'user_id')::bigint,(p_payload->>'role_id')::bigint)returning user_roles.id into id;else update public.user_roles set user_id=(p_payload->>'user_id')::bigint,role_id=(p_payload->>'role_id')::bigint where user_roles.id=p_id;end if;
  delete from public.user_role_sessions s where s.user_id=oldlink.user_id and not exists(select 1 from public.user_roles r where r.user_id=s.user_id and r.role_id=s.role_id);
 elsif p_catalog='user-subsidiaries'then
  if id is null or id=u or(p_payload?'user_id'and(p_payload->>'user_id')::bigint<>id)then raise exception using errcode='42501',message='No puede cambiar sus propios accesos.';end if;
  if jsonb_typeof(p_payload->'subsidiary_ids')is distinct from'array'or jsonb_array_length(p_payload->'subsidiary_ids')=0 or exists(select 1 from jsonb_array_elements(p_payload->'subsidiary_ids')x where jsonb_typeof(x)<>'number'or x::text!~'^[1-9][0-9]*$')then raise exception using errcode='22023',message='Filiales invalidas.';end if;
  d:=access_admin_private.security_sync_user_subsidiaries(id,array(select value::bigint from jsonb_array_elements_text(p_payload->'subsidiary_ids')));
 end if;
 return(select x from jsonb_array_elements(public.security_access_master_list(p_catalog))x where coalesce(x->>'user_id',x->>'role_id')=id::text and p_catalog in('users','roles','user-subsidiaries')or p_catalog='user-roles'and x->>'id'=id::text limit 1);end$$;
create function public.security_delete_access_master(p_id bigint,p_revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=access_admin_private.access('user-roles','delete');r public.user_roles;
begin perform pg_advisory_xact_lock(793152,1);select *into r from public.user_roles where id=p_id for update;
 if not found or r.user_id=u then raise exception using errcode='42501',message='Asignacion no autorizada.';end if;
 if p_revision is distinct from access_admin_private.revision('user-roles',p_id)then raise exception using errcode='55000',message='La asignacion cambio.';end if;
 if access_admin_private.admin_user(r.user_id)and exists(select 1 from public.roles where role_id=r.role_id and is_system_role and lower(btrim(role_name))in('administrador','administrator','admin'))and not exists(select 1 from public.users a where a.is_active and a.user_id<>r.user_id and access_admin_private.admin_user(a.user_id))then raise exception using errcode='42501',message='Conserve al ultimo administrador.';end if;
 delete from public.user_roles where id=p_id;delete from public.user_role_sessions s where s.user_id=r.user_id and not exists(select 1 from public.user_roles m where m.user_id=s.user_id and m.role_id=s.role_id);return true;end$$;

-- Existing permission checks used by invitation flows must share this boundary.
do $patch$declare d text;begin select pg_get_functiondef('public.security_assert_role_access(text,text)'::regprocedure)into d;d:=replace(d,'begin',E'begin\n if p_resource_key in(''security:users'',''security:roles'',''security:user-roles'',''security:user-subsidiaries'',''security:permissions'',''security:role-permissions'',''security:role-access-matrix'')then perform access_admin_private.access(substr(p_resource_key,10),p_action);return;end if;');execute d;end$patch$;
do $$declare t text;c record;p record;begin foreach t in array array['users','roles','user_roles','user_subsidiaries','role_permissions','role_access_matrix','permissions']loop
 execute format('revoke insert,update,delete,truncate,references,trigger on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),references(%I)on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,t);end loop;
 for p in select policyname from pg_policies where schemaname='public'and tablename=t and cmd<>'SELECT'loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('alter table public.%I enable row level security',t);end loop;end$$;
-- Server invitation completion updates only this timestamp; profile/auth secrets remain immutable.
do $$declare t text;p record;predicate text;begin foreach t in array array['users','roles','user_roles','user_subsidiaries','permissions','role_permissions','role_access_matrix']loop
 for p in select policyname from pg_policies where schemaname='public'and tablename=t and cmd='SELECT'loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 predicate:=case t when'users'then'user_id=public.app_user_id()or(access_admin_private.allowed(''users'',''view'')and access_admin_private.target(user_id))'
 when'roles'then'role_id in(select role_id from public.user_roles where user_id=public.app_user_id())or access_admin_private.allowed(''roles'',''view'')'
 when'user_roles'then'user_id=public.app_user_id()or(access_admin_private.allowed(''user-roles'',''view'')and access_admin_private.target(user_id))'
 when'user_subsidiaries'then'user_id=public.app_user_id()or access_admin_private.allowed(''user-subsidiaries'',''view'')'
 when'permissions'then'access_admin_private.allowed(''permissions'',''view'')or permission_id in(select permission_id from public.role_permissions where role_id=public.app_active_role_id())'
 when'role_permissions'then'role_id=public.app_active_role_id()or access_admin_private.allowed(''role-permissions'',''view'')'
 else'role_id=public.app_active_role_id()or access_admin_private.allowed(''role-access-matrix'',''view'')'end;
 execute format('create policy access_admin_read on public.%I for select to authenticated using(%s)',t,predicate);end loop;end$$;
grant update(invitation_accepted_at)on public.users to service_role;
revoke all on all functions in schema access_admin_private from public,anon,authenticated,service_role;
grant execute on function access_admin_private.allowed(text,text),access_admin_private.target(bigint)to authenticated;
do $$declare p record;begin for p in select proc.oid::regprocedure signature from pg_proc proc join pg_namespace n on n.oid=proc.pronamespace where n.nspname='public'and proc.proname in('security_create_user','security_mark_user_invitation_sent','security_prepare_user_password_recovery','security_sync_user_subsidiaries','security_user_subsidiary_assignments','security_user_subsidiary_options','security_role_access_matrix_data','security_save_role_access_matrix','security_access_master_list','security_access_master_options','security_save_access_master','security_delete_access_master','security_save_access_matrix')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',p.signature);execute format('grant execute on function %s to authenticated',p.signature);end loop;end$$;
notify pgrst,'reload schema';
